/**
 * Shared form-validation utilities.
 *
 * Usage pattern:
 *  1. Define a ValidationRule<T>[] array in DOM top-to-bottom section order.
 *  2. Call runValidation(form, rules) → ValidationErrors.
 *  3. Call scrollToFirstErrorSection(errors, rules) to scroll to the first errored section.
 *  4. Use clearFieldErrors(prev, patchedKeys) inside your patch() function for live clearing.
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type ValidationErrors = Record<string, string>;

export interface ValidationRule<T> {
  /** Form-state key — also used as the errors map key. */
  field: string;
  /** DOM element `id` to scroll into view when this field has an error. */
  sectionId: string;
  /**
   * Return an error message string if the form is invalid for this rule,
   * or `null` if the field is valid.
   */
  validate: (form: Partial<T>) => string | null;
}

// ─── Core helpers ─────────────────────────────────────────────────────────────

/**
 * Run all rules in declaration order and collect errors.
 * The first failing rule for each field wins (later rules for the same field are skipped).
 */
export function runValidation<T>(
  form: Partial<T>,
  rules: ValidationRule<T>[],
): ValidationErrors {
  const errors: ValidationErrors = {};
  for (const rule of rules) {
    if (rule.field in errors) continue; // already errored for this field
    const error = rule.validate(form);
    if (error) {
      errors[rule.field] = error;
    }
  }
  return errors;
}

/**
 * Scroll to the DOM section of the **first** rule (in rules-array order) that
 * currently has an error.  Rules array order should match top-to-bottom DOM
 * order so the user always sees the top-most error scrolled into view.
 */
export function scrollToFirstErrorSection<T>(
  errors: ValidationErrors,
  rules: ValidationRule<T>[],
  delay = 120,
): void {
  for (const rule of rules) {
    if (errors[rule.field]) {
      setTimeout(() => {
        document.getElementById(rule.sectionId)?.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      }, delay);
      return;
    }
  }
}

/**
 * Remove errors for any key that appears in patchedKeys.
 * Returns the *same* object reference if nothing changed (avoids unnecessary re-renders).
 */
export function clearFieldErrors(
  errors: ValidationErrors,
  patchedKeys: string[],
): ValidationErrors {
  if (!patchedKeys.some((k) => k in errors)) return errors;
  const next = { ...errors };
  patchedKeys.forEach((k) => delete next[k]);
  return next;
}
